/// Binary search the glyph table (sorted by codepoint).
pub fn glyph(ch: char) -> Option<&'static GlyphDef> {
    GLYPHS.binary_search_by_key(&(ch as u32), |g| g.ch).ok().map(|i| &GLYPHS[i])
}

/// Providers skipped by the generator (ttf/legacy, unifont is empty in current versions).
pub const SKIPPED_PROVIDERS: usize = 0;
